(function () {
  function pair(portuguese, spanish) {
    return { 'pt-BR': portuguese, es: spanish };
  }

  var header = [
    pair('<span class="dot">●</span> Legal', '<span class="dot">●</span> Legal'),
    pair('Política de privacidade', 'Política de privacidad'),
    pair('Última atualização: 02-09-2026', 'Última actualización: 02-09-2026'),
    pair('O Svartifoss ("o app", "nós", "nosso") é um app companheiro para Wear OS que permite que um relógio pareado controle a reprodução de músicas no telefone. Esta política explica quais informações o app acessa, o que ele armazena e o que — se algo — sai do seu dispositivo.', 'Svartifoss ("la app", "nosotros", "nuestro") es una app compañera para Wear OS que permite que un reloj emparejado controle la reproducción de música en tu teléfono. Esta política explica qué información accede la app, qué almacena y qué — si algo — sale de tu dispositivo.'),
    pair('<strong>Em resumo:</strong> o Svartifoss não exige conta para reprodução, controle do relógio ou navegação pelos temas da comunidade; não opera um servidor próprio; e não vende nem compartilha seus dados com anunciantes. O telefone e o relógio se comunicam diretamente pela sua conexão local Bluetooth/Wi-Fi. As verificações opcionais de atualização e a galeria de temas da comunidade, quando ativada, acessam o GitHub Pages. Curtir, instalar ou denunciar um tema publicado não exige conta: o app cria silenciosamente uma conta anônima do Firebase Authentication para essas ações, e o Google Cloud Firestore mantém o registro privado sob esse identificador anônimo. <strong>Enviar</strong> um tema é a única ação que pede login com o Google e, mesmo assim, o nome e o e-mail da sua conta Google não são publicados. O app do telefone também inclui Google Firebase Crashlytics e Analytics para diagnósticos, além do Firebase Cloud Messaging para avisos ocasionais do desenvolvedor. Relatórios de falha e avisos podem ser desativados a qualquer momento — consulte <a href="#crash-reports">Relatórios de falha</a> e <a href="#announcement-notifications">Avisos</a> abaixo. Uma configuração separada, desativada por padrão, também pode buscar capas dos seus atalhos de playlists diretamente no serviço de streaming — consulte <a href="#streaming-shortcut-artwork-optional">Capas de atalhos</a> abaixo.', '<strong>En resumen:</strong> Svartifoss no requiere una cuenta para reproducir, controlar el reloj o explorar temas de la comunidad; no opera un servidor propio; y no vende ni comparte tus datos con anunciantes. El teléfono y el reloj se comunican directamente mediante tu conexión local Bluetooth/Wi-Fi. Las comprobaciones opcionales de actualizaciones y la galería de temas de la comunidad, cuando se activa, contactan con GitHub Pages. Dar «Me gusta», instalar o denunciar un tema publicado no requiere una cuenta: la app crea silenciosamente una cuenta anónima de Firebase Authentication para esas acciones y Google Cloud Firestore guarda el registro privado bajo ese identificador anónimo. <strong>Enviar</strong> un tema es la única acción que pide iniciar sesión con Google y, aun así, el nombre y el correo de tu cuenta de Google no se publican. La app del teléfono también incluye Google Firebase Crashlytics y Analytics para diagnósticos, además de Firebase Cloud Messaging para avisos ocasionales del desarrollador. Los informes de fallos y avisos se pueden desactivar en cualquier momento — consulta <a href="#crash-reports">Informes de fallos</a> y <a href="#announcement-notifications">Avisos</a> más abajo. Otra opción, desactivada por defecto, también puede obtener portadas para tus accesos directos de listas directamente del servicio de streaming — consulta <a href="#streaming-shortcut-artwork-optional">Portadas de accesos directos</a> más abajo.')
  ];

  var toc = [
    pair('Nesta página', 'En esta página'),
    pair('Acesso e permissões', 'Acceso y permisos'),
    pair('Armazenamento local', 'Almacenamiento local'),
    pair('Relatórios de falha', 'Informes de fallos'),
    pair('Avisos', 'Avisos'),
    pair('Temas da comunidade', 'Temas de la comunidad'),
    pair('Capas de atalhos', 'Portadas de accesos directos'),
    pair('Capas da fila', 'Portadas de la cola'),
    pair('Detalhes da faixa', 'Detalles de la canción'),
    pair('Letras de músicas', 'Letras de canciones'),
    pair('Diagnósticos de uso', 'Diagnósticos de uso'),
    pair('O que não fazemos', 'Lo que no hacemos'),
    pair('Privacidade infantil', 'Privacidad infantil'),
    pair('Código aberto', 'Código abierto'),
    pair('Contato', 'Contacto')
  ];

  var sections = {
    access: [
      pair('O que o app precisa acessar e por quê', 'Qué necesita acceder la app y por qué'),
      pair('Acesso às notificações <em>(permissão "Acesso às notificações" do Android)</em>', 'Acceso a notificaciones <em>(permiso «Acceso a notificaciones» de Android)</em>'),
      pair('O Svartifoss solicita <strong>acesso às notificações</strong> para saber qual app está reproduzindo música e ler seus metadados de sessão de mídia (título da faixa, artista, capa, posição, estado aleatório/repetição). Se você escolher <strong>Do app de mídia atual</strong> para o painel de ações rápidas, ele também lê até quatro rótulos de ações, ícones e intents locais dos botões da notificação de mídia ativa desse app. Os rótulos e ícones são espelhados apenas no seu relógio pareado; os intents dos botões permanecem no telefone e só são executados quando você toca no botão correspondente do relógio.', 'Svartifoss solicita <strong>acceso a notificaciones</strong> para saber qué app está reproduciendo música y leer sus metadatos de sesión multimedia (título, artista, portada, posición y estado aleatorio/repetición). Si eliges <strong>Desde la app multimedia actual</strong> para el panel de acciones rápidas, también lee hasta cuatro etiquetas de acciones, iconos e intents locales de los botones de la notificación multimedia activa de esa app. Las etiquetas e iconos solo se reflejan en tu reloj emparejado; los intents permanecen en el teléfono y solo se ejecutan cuando tocas el botón correspondiente del reloj.'),
      pair('Esta permissão <strong>não</strong> é usada para ler o conteúdo das suas mensagens, e-mails ou notificações não relacionadas. O Svartifoss não armazena, transmite para um servidor nem registra esse conteúdo.', 'Este permiso <strong>no</strong> se usa para leer el contenido de tus mensajes, correos ni notificaciones no relacionadas. Svartifoss no almacena, transmite a un servidor ni registra ese contenido.'),
      pair('Comunicação entre telefone e relógio', 'Comunicación entre el teléfono y el reloj'),
      pair('Toda a comunicação entre o app do telefone e o app do relógio acontece pela API Wearable Data Layer — uma conexão local e direta entre os seus dois dispositivos pareados, via Bluetooth ou Wi-Fi local. Isso não passa por nenhum servidor operado por nós e não exige conexão com a internet nem uma conta Google além do que o próprio dispositivo já precisa para manter o relógio pareado.', 'Toda la comunicación entre la app del teléfono y la app del reloj ocurre mediante la API Wearable Data Layer — una conexión local y directa entre tus dos dispositivos emparejados, por Bluetooth o Wi-Fi local. No pasa por ningún servidor operado por nosotros y no requiere conexión a internet ni una cuenta de Google más allá de lo que el dispositivo ya necesita para mantener el reloj emparejado.'),
      pair('Outras permissões', 'Otros permisos'),
      pair('Permissão', 'Permiso'),
      pair('Para que serve', 'Para qué sirve'),
      pair('Serviço em primeiro plano / "Publicar notificações"', 'Servicio en primer plano / «Publicar notificaciones»'),
      pair('Mantém a conexão telefone↔relógio ativa enquanto a música toca, exibida como uma notificação persistente (exigida pelo Android para apps de mídia em segundo plano). Também é necessária para exibir os avisos opcionais do desenvolvedor descritos abaixo.', 'Mantiene activa la conexión teléfono↔reloj mientras suena la música, mostrada como una notificación persistente (requerida por Android para apps multimedia en segundo plano). También es necesaria para mostrar los avisos opcionales del desarrollador descritos abajo.'),
      pair('Fotos', 'Fotos'),
      pair('Só é usada se você escolher explicitamente salvar a capa atual na galeria de fotos do dispositivo. Nada é salvo sem que você toque nessa opção.', 'Solo se usa si eliges explícitamente guardar la portada actual en la galería de fotos del dispositivo. No se guarda nada hasta que tocas esa opción.'),
      pair('Vibrar', 'Vibración'),
      pair('Feedback tátil no relógio ao pressionar um botão, se você ativar essa configuração.', 'Respuesta háptica en el reloj al pulsar un botón, si activas esa opción.'),
      pair('Executar tarefas do Tasker', 'Ejecutar tareas de Tasker'),
      pair('Só é relevante se você tiver o app Tasker separado instalado e escolher vincular uma tarefa do Tasker a um botão. O Svartifoss não lê os dados do Tasker — apenas dispara uma tarefa que você configurou.', 'Solo es relevante si tienes instalada la app independiente Tasker y eliges vincular una tarea de Tasker a un botón. Svartifoss no lee los datos de Tasker: solo activa una tarea que tú configuraste.'),
      pair('Música e áudio (Android 13+) / Armazenamento (versões antigas)', 'Música y audio (Android 13+) / Almacenamiento (versiones antiguas)'),
      pair('Só é usada para ler capas de itens da fila de reprodução quando o app de música as publica como referências na sua biblioteca, em vez de imagens. É solicitada em Configurações → Apps, nunca na inicialização, e lida apenas localmente — nada é enviado. Se você recusar, a fila mostra miniaturas vazias. Em versões muito antigas do Android, a mesma permissão legada de armazenamento também cobre salvar a capa atual na galeria, o que só acontece se você tocar nessa opção.', 'Solo se usa para leer portadas de elementos de la cola cuando la app de música las publica como referencias de tu biblioteca en lugar de imágenes. Se solicita desde Ajustes → Apps, nunca al iniciar, y solo se lee localmente — no se sube nada. Si la rechazas, la cola muestra miniaturas vacías. En versiones muy antiguas de Android, el mismo permiso de almacenamiento también permite guardar la portada actual en la galería, lo que solo ocurre si tocas esa opción.'),
      pair('Internet', 'Internet'),
      pair('É usada para verificações opcionais de atualização, a galeria de temas da comunidade, Firebase Authentication e Firestore quando você curte, instala ou denuncia um tema ou usa o filtro privado Curtidos (com conta anônima, sem login), e o Google Sign-In somente quando você envia um tema explicitamente. Também é usada para os diagnósticos do Firebase descritos abaixo, buscar letras quando você abre a tela de letras no relógio e — apenas se ativados — buscar capas de atalhos no serviço de streaming e baixar capas da fila que o app de música publicou como links. O espelhamento e o controle básicos da reprodução funcionam localmente entre os seus dois dispositivos.', 'Se usa para comprobaciones opcionales de actualizaciones, la galería de temas de la comunidad, Firebase Authentication y Firestore cuando marcas como favorito, instalas o denuncias un tema o usas el filtro privado Favoritos (con cuenta anónima y sin iniciar sesión), y Google Sign-In solo cuando envías un tema explícitamente. También se usa para los diagnósticos de Firebase descritos abajo, buscar letras cuando abres la pantalla de letras en el reloj y — solo si los activas — obtener portadas de accesos directos del servicio de streaming y descargar portadas de la cola que la app de música publicó como enlaces. El reflejo y el control básicos de la reproducción funcionan localmente entre tus dos dispositivos.')
    ],
    'local-storage': [
      pair('O que fica armazenado localmente no telefone', 'Qué se almacena localmente en el teléfono'),
      pair('Normalmente, o conteúdo a seguir fica apenas no armazenamento privado do app no telefone. A exceção é um tema que você envia expressamente para a fila de moderação dos temas da comunidade, descrita abaixo.', 'Normalmente, lo siguiente permanece solo en el almacenamiento privado de la app en tu teléfono. La excepción es un tema que envías expresamente a la cola de moderación de temas de la comunidad, descrita abajo.'),
      pair('Sua configuração de botões e gestos (o que cada botão, zona de toque ou gesto faz).', 'Tu configuración de botones y gestos (qué hace cada botón, zona táctil o gesto).'),
      pair('Seu histórico de buscas e atalhos de playlists, se você usar esses recursos.', 'Tu historial de búsquedas y accesos directos a listas, si usas esas funciones.'),
      pair('Um pequeno histórico local das faixas reproduzidas recentemente, usado como alternativa quando um app não expõe uma fila de reprodução real.', 'Un breve historial local de canciones reproducidas recientemente, usado como alternativa cuando una app no expone una cola real.'),
      pair('Sua biblioteca privada de temas e outras preferências do app (tema, cores, tempos limite etc.). Um perfil só sai do dispositivo se você o selecionar para um envio explícito de tema da comunidade.', 'Tu biblioteca privada de temas y otras preferencias de la app (tema, colores, tiempos de espera, etc.). Un perfil solo sale del dispositivo si lo seleccionas para enviar explícitamente un tema de la comunidad.'),
      pair('Um cache descartável do catálogo público de temas da comunidade, arquivos de temas e capturas dos autores depois que você abre a galeria. Ele contém apenas o JSON público servido pelo GitHub Pages deste projeto, não entra nos backups de configuração e pode ser limpo pelos controles de cache do Android.', 'Una caché desechable del catálogo público de temas de la comunidad, archivos de temas y capturas de los autores después de abrir la galería. Solo contiene el JSON público servido por el GitHub Pages de este proyecto, no forma parte de las copias de seguridad de configuración y se puede borrar desde los controles de caché de Android.'),
      pair('Desinstalar o app remove todos esses dados. Se você usar o recurso Exportar configuração, o arquivo será salvo onde escolher (por exemplo, no armazenamento do dispositivo ou em um drive na nuvem) — essa cópia é sua, está sob seu controle e nós nunca a vemos.', 'Desinstalar la app elimina todos estos datos. Si usas la función Exportar configuración, el archivo se guarda donde elijas (por ejemplo, en el almacenamiento del dispositivo o en una nube): esa copia es tuya, está bajo tu control y nunca la vemos.')
    ],
    'crash-reports': [
      pair('Relatórios de falha', 'Informes de fallos'),
      pair('O Svartifoss usa o <strong>Firebase Crashlytics</strong> (um serviço do Google) para receber relatórios quando o app apresenta falhas, permitindo encontrar e corrigir problemas. Um relatório pode incluir: rastreamento da pilha, versão do Android e modelo do dispositivo e pequenas linhas de log de diagnóstico que o app já grava durante a execução — essas linhas ocasionalmente incluem o nome da faixa ou do app que estava tocando, por fazerem parte da operação normal, mas nunca suas mensagens pessoais, contatos ou conteúdo de notificações de outros apps.', 'Svartifoss usa <strong>Firebase Crashlytics</strong> (un servicio de Google) para recibir informes cuando la app falla, de modo que podamos encontrar y corregir errores. Un informe puede incluir: una traza de pila, la versión de Android y el modelo del dispositivo y breves líneas de registro de diagnóstico que la app ya escribe durante su ejecución — esas líneas pueden incluir ocasionalmente el nombre de la canción o app que sonaba, porque forman parte del funcionamiento normal, pero nunca tus mensajes personales, contactos ni contenido de notificaciones de otras apps.'),
      pair('Os relatórios de falha vêm <strong>ativados por padrão</strong>. Você pode desativá-los em <strong>Configurações → Dados e suporte → Privacidade → Enviar relatórios de falha</strong>. Desativar impede que o Svartifoss adicione logs personalizados ou relatórios não fatais ao Crashlytics e exclui relatórios ainda na fila do dispositivo sem enviá-los. O upload automático do Crashlytics permanece desativado o tempo todo; quando essa configuração está ativa, o Svartifoss envia relatórios finalizados explicitamente somente depois de ler sua escolha na inicialização. Não é possível recuperar um relatório que já tenha sido enviado antes da sua desativação.', 'Los informes de fallos están <strong>activados por defecto</strong>. Puedes desactivarlos en <strong>Ajustes → Datos y soporte → Privacidad → Enviar informes de fallos</strong>. Al desactivarlos, Svartifoss deja de añadir registros personalizados o informes no fatales a Crashlytics y elimina los informes que sigan en la cola del dispositivo sin enviarlos. La carga automática de Crashlytics permanece desactivada en todo momento; cuando esta opción está activa, Svartifoss solo envía informes finalizados explícitamente después de leer tu elección al iniciar. No puede recuperar un informe que ya se hubiera subido antes de que eligieras no participar.'),
      pair('Esses dados são enviados à infraestrutura Firebase do Google, regida pela <a href="https://policies.google.com/privacy">Política de privacidade do Google</a> e pelos <a href="https://firebase.google.com/support/privacy">termos de processamento de dados do Firebase</a>. Não temos acesso a dados não relacionados que o Google possa manter por meio de outros serviços.', 'Estos datos se envían a la infraestructura Firebase de Google, regida por la <a href="https://policies.google.com/privacy">Política de privacidad de Google</a> y los <a href="https://firebase.google.com/support/privacy">términos de tratamiento de datos de Firebase</a>. No tenemos acceso a otros datos no relacionados que Google pueda conservar mediante sus servicios.')
    ],
    'announcement-notifications': [
      pair('Avisos', 'Avisos'),
      pair('O Svartifoss usa o <strong>Firebase Cloud Messaging</strong> (um serviço do Google) para que o desenvolvedor envie notificações ocasionais — por exemplo, sobre uma nova versão ou um aviso importante. Não há conta Svartifoss nem servidor nosso envolvido: cada instalação se inscreve em um único tópico FCM compartilhado e uma notificação enviada a esse tópico chega a todos os dispositivos inscritos. Não recebemos nem mantemos uma lista de usuários, dispositivos ou identificadores de instalação por meio desse recurso — a infraestrutura Firebase do Google encaminha a mensagem aos dispositivos inscritos sem nos expor essa lista.', 'Svartifoss usa <strong>Firebase Cloud Messaging</strong> (un servicio de Google) para que el desarrollador envíe notificaciones ocasionales — por ejemplo, sobre una nueva versión o un aviso importante. No hay una cuenta de Svartifoss ni un servidor nuestro: cada instalación se suscribe a un único tema FCM compartido y una notificación enviada a ese tema llega a todos los dispositivos suscritos. No recibimos ni conservamos una lista de usuarios, dispositivos o identificadores de instalación mediante esta función — la infraestructura Firebase de Google dirige el mensaje a los dispositivos suscritos sin mostrarnos esa lista.'),
      pair('Uma notificação pode incluir um título, uma mensagem curta e um link opcional que abre quando você toca nela (por exemplo, uma página de lançamento). O Svartifoss não usa esse canal para publicidade e não envia nada com base na sua atividade de reprodução, localização ou qualquer outro dado do dispositivo — tudo que é enviado é escrito pelo desenvolvedor no momento do envio.', 'Una notificación puede incluir un título, un mensaje breve y un enlace opcional que se abre al tocarla (por ejemplo, una página de lanzamiento). Svartifoss no usa este canal para publicidad ni envía nada basándose en tu actividad de escucha, ubicación u otros datos del dispositivo — todo lo que se envía lo escribe el desarrollador en el momento del envío.'),
      pair('Os avisos vêm <strong>ativados por padrão</strong>. Você pode desativá-los em <strong>Configurações → Dados e suporte → Privacidade → Avisos</strong>. Desativar cancela a inscrição desta instalação no tópico; uma mensagem enviada enquanto você estiver inscrito não chegará a este dispositivo. A permissão de notificações do próprio Android também se aplica além dessa configuração.', 'Los avisos están <strong>activados por defecto</strong>. Puedes desactivarlos en <strong>Ajustes → Datos y soporte → Privacidad → Avisos</strong>. Al desactivarlos, esta instalación deja de estar suscrita al tema; un mensaje enviado mientras no estés suscrito no llegará a este dispositivo. El permiso de notificaciones del propio Android también se aplica además de esta opción.'),
      pair('Isso usa a infraestrutura Firebase do Google, regida pela <a href="https://policies.google.com/privacy">Política de privacidade do Google</a> e pelos <a href="https://firebase.google.com/support/privacy">termos de processamento de dados do Firebase</a>.', 'Esto usa la infraestructura Firebase de Google, regida por la <a href="https://policies.google.com/privacy">Política de privacidad de Google</a> y los <a href="https://firebase.google.com/support/privacy">términos de tratamiento de datos de Firebase</a>.')
    ],
    'community-themes': [
      pair('Temas da comunidade', 'Temas de la comunidad'),
      pair('Navegar e instalar', 'Explorar e instalar'),
      pair('Abrir <strong>Temas da comunidade</strong> na tela de temas do relógio solicita um catálogo público e, quando necessário para uma prévia ou instalação, arquivos JSON públicos de temas do site <a href="https://gabrielluizone.github.io/Svartifoss/">GitHub Pages</a> deste projeto. Nada é solicitado até você abrir essa tela. A busca, os filtros por layout base e a ordenação por mais novos ou mais curtidos acontecem localmente sobre esse catálogo público baixado. Navegar não inicia o Google Sign-In nem grava no Firebase, e não envia sua reprodução, biblioteca, temas salvos, dados da conta ou identificador do dispositivo. A solicitação identifica o app apenas com um user-agent genérico do Svartifoss, enquanto o GitHub necessariamente recebe informações comuns da requisição, como seu endereço IP, sob seus próprios termos de privacidade.', 'Abrir <strong>Temas de la comunidad</strong> desde la pantalla de temas del reloj solicita un catálogo público y, cuando hace falta para una previsualización o instalación, archivos JSON públicos de temas del sitio <a href="https://gabrielluizone.github.io/Svartifoss/">GitHub Pages</a> de este proyecto. No se solicita nada hasta que abres esa pantalla. La búsqueda, los filtros por diseño base y el orden por novedades o favoritos se realizan localmente sobre el catálogo público descargado. Explorar no inicia Google Sign-In ni escribe en Firebase, y no envía tu reproducción, biblioteca, temas guardados, datos de cuenta ni identificador del dispositivo. La solicitud identifica la app solo con un user-agent genérico de Svartifoss, mientras que GitHub recibe necesariamente información normal de la solicitud, como tu dirección IP, según sus propios términos de privacidad.'),
      pair('Um cartão abre uma página de detalhes antes que um tema seja adicionado a <strong>Meus temas</strong>. Os cartões da galeria continuam sintéticos e a página de detalhes renderiza localmente as prévias de Player, tela sempre ativa, Volume, Progresso, Painel rápido e Fila a partir do perfil, com rótulos, tempos e dados de fila de exemplo. A prévia pode mostrar apenas a capa atual já mantida na memória do telefone. Ela não usa o título, artista, posição, fila ou outros metadados de mídia ao vivo; a capa nunca é enviada ou transmitida.', 'Una tarjeta abre una página de detalles antes de añadir un tema a <strong>Mis temas</strong>. Las tarjetas de la galería siguen siendo sintéticas y la página de detalles renderiza localmente las previsualizaciones de Player, pantalla siempre activa, Volumen, Progreso, Panel rápido y Cola desde el perfil, con etiquetas, tiempos y datos de cola de muestra. La previsualización puede mostrar solo la portada actual que ya está en la memoria del teléfono. No usa el título, artista, posición, cola ni otros metadatos multimedia en vivo; la portada nunca se sube ni se transmite.'),
      pair('<strong>O Svartifoss nunca captura nada do seu relógio.</strong> Ele não solicita, tira nem dispara uma captura de tela no relógio, e o relógio nunca envia ao app uma imagem da própria tela.', '<strong>Svartifoss nunca captura nada de tu reloj.</strong> No solicita, toma ni activa una captura de pantalla del reloj, y el reloj nunca envía a la app una imagen de su propia pantalla.'),
      pair('Alguns temas carregam <strong>uma fotografia publicada pelo autor</strong>: uma captura que o autor fez no próprio relógio e escolheu anexar ao enviar o tema. Quando existe uma, a página de detalhes mostra o Player do autor em vez da prévia gerada, identificado como tal, com um controle para voltar à prévia gerada. Essa escolha é lembrada, e desativá-la faz o app parar de solicitar essas imagens, em vez de apenas escondê-las. A imagem é um arquivo público servido pelo mesmo GitHub Pages do restante do catálogo, solicitado apenas quando você abre os detalhes de um tema que possui uma e armazenado no cache descartável do app. O catálogo, perfil e arquivos de imagem baixados são conteúdo público e não fazem parte de um backup de configuração.', 'Algunos temas incluyen <strong>una fotografía publicada por su autor</strong>: una captura que el autor tomó en su propio reloj y eligió adjuntar al enviar el tema. Cuando existe, la página de detalles muestra el Player del autor en lugar de la previsualización generada, etiquetado como tal, con un control para volver a la generada. Esta elección se recuerda y desactivarla hace que la app deje de solicitar esas imágenes en lugar de limitarse a ocultarlas. La imagen es un archivo público servido por el mismo GitHub Pages que el resto del catálogo, solicitado solo al abrir los detalles de un tema que la tiene y guardado en la caché desechable de la app. El catálogo, perfil y archivos de imagen descargados son contenido público y no forman parte de una copia de seguridad de configuración.'),
      pair('Curtidas', 'Favoritos'),
      pair('<strong>Curtir nunca pede login.</strong> Tocar em <strong>Curtir</strong>, tocar novamente para desfazer e selecionar o filtro privado <strong>Curtidos</strong> funciona sem conta Google e sem qualquer aviso. Para armazenar a reação, o app cria uma <strong>conta anônima do Firebase Authentication</strong> na primeira vez que você usa uma dessas ações. Uma conta anônima não tem nome, e-mail nem vínculo com uma conta Google: é apenas um identificador opaco mantido no armazenamento local do app no telefone.', '<strong>Dar «Me gusta» nunca pide iniciar sesión.</strong> Tocar en <strong>Me gusta</strong>, tocar de nuevo para deshacerlo y seleccionar el filtro privado <strong>Favoritos</strong> funciona sin cuenta de Google y sin avisos. Para guardar la reacción, la app crea una <strong>cuenta anónima de Firebase Authentication</strong> la primera vez que usas una de esas acciones. Una cuenta anónima no tiene nombre, correo ni vínculo con una cuenta de Google: es solo un identificador opaco guardado en el almacenamiento local de la app en el teléfono.'),
      pair('Como esse identificador é local, limpar os dados do app ou reinstalá-lo produz um novo, e as reações deixadas sob o identificador anterior permanecem no Firestore sem poderem mais ser acessadas pelo seu telefone. Isso é aceito, não contornado: as contagens são um sinal aproximado de popularidade, não uma votação, e a alternativa seria exigir identidade para tocar em um coração.', 'Como ese identificador es local, borrar los datos de la app o reinstalarla crea uno nuevo, y las reacciones del identificador anterior permanecen en Firestore sin que tu teléfono pueda acceder a ellas. Es una consecuencia aceptada: los recuentos son una señal aproximada de popularidad, no una votación, y la alternativa sería exigir una identidad para tocar un corazón.'),
      pair('Se depois você conectar o Google pela <strong>Conta da comunidade</strong> nas Configurações ou ao enviar um tema, essa conta anônima é atualizada no lugar da anterior, para que as reações feitas antes da conexão continuem pertencendo a você.', 'Si más tarde conectas Google desde <strong>Cuenta de la comunidad</strong> en Ajustes o al enviar un tema, esa cuenta anónima se actualiza en lugar de sustituirse, por lo que las reacciones anteriores a la conexión siguen siendo tuyas.'),
      pair('Cada curtida é um documento privado por conta em <code>communityThemeLikes/&lt;theme ID&gt;/voters/&lt;Firebase Auth UID&gt;</code>. Ele contém apenas uma versão do esquema e um registro de data e hora do servidor Firestore; não contém nome nem e-mail — uma conta anônima não tem esses dados. As regras do Firestore permitem criar, ler ou excluir apenas a sua própria reação. Elas não permitem que nenhum cliente liste votantes, leia a reação de outra pessoa, atualize uma reação ou escreva uma contagem pública.', 'Cada favorito es un documento privado por cuenta en <code>communityThemeLikes/&lt;theme ID&gt;/voters/&lt;Firebase Auth UID&gt;</code>. Solo contiene una versión del esquema y una marca de tiempo del servidor Firestore; no contiene nombre ni correo — una cuenta anónima no tiene esos datos. Las reglas de Firestore solo permiten crear, leer o eliminar tu propia reacción. No permiten a ningún cliente listar votantes, leer la reacción de otra persona, actualizar una reacción ni escribir un recuento público.'),
      pair('O filtro <strong>Curtidos</strong> não lista uma coleção de votantes nem descobre IDs de temas pelo Firebase. Ele verifica apenas o documento do UID atual do Firebase Auth no caminho privado conhecido para cada ID já público no catálogo baixado.', 'El filtro <strong>Favoritos</strong> no lista una colección de votantes ni descubre IDs de temas mediante Firebase. Solo comprueba el documento del UID actual de Firebase Auth en la ruta privada conocida para cada ID ya público del catálogo descargado.'),
      pair('O catálogo público mostra apenas uma contagem agregada confiável. O publicador do GitHub contabiliza as reações privadas e depois grava o total no catálogo estático, então uma curtida ou remoção pode levar até a próxima publicação que o reescreva — no máximo cerca de uma semana — para aparecer ou afetar a ordenação por <strong>mais curtidos</strong>. Sua própria reação aparece imediatamente no seu dispositivo. A contagem pública nunca identifica quem reagiu.', 'El catálogo público solo muestra un recuento agregado y confiable. El publicador de GitHub cuenta las reacciones privadas y después escribe el total en el catálogo estático, por lo que un favorito o su eliminación puede tardar hasta la siguiente publicación que lo reescriba — como máximo alrededor de una semana — en aparecer o afectar el orden de <strong>más favoritos</strong>. Tu propia reacción aparece inmediatamente en tu dispositivo. El recuento público nunca identifica quién reaccionó.'),
      pair('Contagens de downloads', 'Recuentos de instalaciones'),
      pair('Cada cartão da galeria e página de detalhes mostra quantas pessoas instalaram o tema. Como o catálogo é um arquivo estático servido pelo GitHub Pages, o servidor nunca observa um download — atualizar o catálogo ou buscar um perfil para pré-visualização não é contado e não poderia ser distinguido de uma navegação.', 'Cada tarjeta de la galería y página de detalles muestra cuántas personas instalaron el tema. Como el catálogo es un archivo estático servido por GitHub Pages, el servidor nunca observa una descarga — actualizar el catálogo o obtener un perfil para previsualizarlo no se cuenta y no se puede distinguir de una navegación.'),
      pair('O que é contado é o momento em que uma instalação realmente é concluída no telefone. Adicionar um tema a <strong>Meus temas</strong> pela galeria grava um documento privado em <code>communityThemeInstalls/&lt;theme ID&gt;/installers/&lt;Firebase Auth UID&gt;</code>, contendo apenas uma versão do esquema e um registro de data e hora do servidor Firestore — sem nome, e-mail, identificador de dispositivo ou qualquer informação sobre o telefone ou sua música. Usa a mesma conta anônima silenciosa descrita em <a href="#likes">Curtidas</a> e nunca pede login. As regras do Firestore permitem criar apenas o seu próprio documento; nenhum cliente pode listar instaladores, ler o documento de outra pessoa, alterá-lo ou escrever uma contagem pública. Se a gravação falhar por qualquer motivo, a instalação ainda é concluída — nada do seu tema depende dela.', 'Lo que se cuenta es el momento en que una instalación se completa realmente en un teléfono. Añadir un tema a <strong>Mis temas</strong> desde la galería escribe un documento privado en <code>communityThemeInstalls/&lt;theme ID&gt;/installers/&lt;Firebase Auth UID&gt;</code>, que solo contiene una versión del esquema y una marca de tiempo del servidor Firestore — sin nombre, correo, identificador del dispositivo ni nada sobre el teléfono o su música. Usa la misma cuenta anónima silenciosa descrita en <a href="#likes">Favoritos</a> y nunca pide iniciar sesión. Las reglas de Firestore solo permiten crear tu propio documento; ningún cliente puede listar instaladores, leer el documento de otra persona, cambiarlo ni escribir un recuento público. Si la escritura falla por cualquier motivo, la instalación se completa igualmente — nada de tu tema depende de ella.'),
      pair('Ao contrário de uma curtida, um registro de instalação não pode ser removido pelo app, e remover o tema de <strong>Meus temas</strong> não diminui o número: ele registra que um download aconteceu, não que o tema continua instalado. Assim como nas curtidas, o total público é agregado pelo publicador confiável do GitHub e pode levar até a próxima execução — no máximo cerca de uma semana — para mudar. Excluir sua conta da comunidade remove seus próprios registros de instalação.', 'A diferencia de un favorito, el registro de instalación no puede eliminarse desde la app, y quitar el tema de <strong>Mis temas</strong> no reduce el número: registra que ocurrió una descarga, no que el tema siga instalado. Como con los favoritos, el total público lo agrega el publicador confiable de GitHub y puede tardar hasta su siguiente ejecución — como máximo alrededor de una semana — en cambiar. Eliminar tu cuenta de la comunidad elimina tus propios registros de instalación.'),
      pair('Denunciar um tema', 'Denunciar un tema'),
      pair('Toda página de detalhes de um tema publicado tem um controle <strong>Denunciar tema</strong>. Denunciar também não exige conta Google: usa a mesma conta anônima silenciosa de uma curtida, porque exigir que alguém se identifique antes de sinalizar conteúdo ofensivo coloca o custo sobre a pessoa errada.', 'La página de detalles de cada tema publicado tiene un control <strong>Denunciar tema</strong>. Denunciar tampoco requiere una cuenta de Google: usa la misma cuenta anónima silenciosa que un favorito, porque pedirle a alguien que se identifique antes de señalar contenido ofensivo pone el coste en la persona equivocada.'),
      pair('Uma denúncia é um documento privado em <code>communityThemeReports/&lt;theme ID&gt;/themeReporters/&lt;Firebase Auth UID&gt;</code>, contendo uma versão do esquema, um registro de data e hora do servidor Firestore, um motivo escolhido de uma lista fixa e — somente se você digitar um — uma nota curta de no máximo 300 caracteres. Nenhuma outra informação sobre você, seu telefone ou sua música é incluída.', 'Una denuncia es un documento privado en <code>communityThemeReports/&lt;theme ID&gt;/themeReporters/&lt;Firebase Auth UID&gt;</code> que contiene una versión del esquema, una marca de tiempo del servidor Firestore, un motivo elegido de una lista fija y — solo si escribes una — una nota breve de un máximo de 300 caracteres. No incluye nada más sobre ti, tu teléfono o tu música.'),
      pair('As denúncias <strong>não são públicas</strong>. Nenhuma contagem é publicada no catálogo, nenhum cliente pode ler a denúncia de outra pessoa e o autor do tema denunciado nunca pode ler denúncias sobre ele nem descobrir quem o denunciou. Somente os moderadores do projeto podem ler a fila. Uma denúncia não pode ser editada ou retirada depois de enviada, e apenas uma é mantida por conta e por tema.', 'Las denuncias <strong>no son públicas</strong>. Nunca se publica ningún recuento en el catálogo, ningún cliente puede leer la denuncia de otra persona y el autor del tema denunciado nunca puede leer denuncias sobre él ni saber quién las presentó. Solo los moderadores del proyecto pueden leer la cola. Una denuncia no se puede editar ni retirar después de enviarla, y solo se conserva una por cuenta y tema.'),
      pair('Os moderadores podem deixar o tema no ar, corrigir seu nome público ou retirá-lo da galeria — as mesmas ações disponíveis para qualquer anúncio. Quando um tema é retirado, as denúncias sobre ele são excluídas junto: depois que o anúncio desaparece, a única coisa que ainda registram é quem reclamou de quê. Excluir sua conta da comunidade também remove as denúncias que você fez.', 'Los moderadores pueden dejar el tema en su sitio, corregir su nombre público o retirarlo de la galería — las mismas acciones disponibles para cualquier anuncio. Cuando se retira un tema, sus denuncias se eliminan con él: una vez desaparecido el anuncio, lo único que siguen registrando es quién se quejó de qué. Eliminar tu cuenta de la comunidad también elimina las denuncias que presentaste.'),
      pair('Enviar um tema', 'Enviar un tema'),
      pair('Enviar é separado de navegar. Você pode conectar o Google explicitamente em <strong>Configurações → Geral → Temas da comunidade → Conta da comunidade</strong> ou escolher <strong>Enviar para a comunidade</strong> para um tema salvo privado e de sua propriedade e tocar em <strong>Entrar e enviar</strong>. O Firebase mantém essa conexão neste dispositivo, então envios posteriores a reutilizam sem mostrar o seletor de conta novamente. Antes de enviar um tema, o app cria e verifica localmente um perfil público novo. A verificação atual exige que pelo menos <strong>12</strong> valores de configuração sejam diferentes da face base selecionada; isso é um filtro de elegibilidade, não uma promessa de aprovação.', 'Enviar es independiente de explorar. Puedes conectar Google explícitamente desde <strong>Ajustes → General → Temas de la comunidad → Cuenta de la comunidad</strong>, o elegir <strong>Enviar a la comunidad</strong> para un tema guardado privado y de tu propiedad y tocar <strong>Iniciar sesión y enviar</strong>. Firebase conserva esa conexión en este dispositivo, por lo que los envíos posteriores la reutilizan sin volver a mostrar el selector de cuenta. Antes de enviar un tema, la app crea y comprueba localmente un perfil público nuevo. La comprobación actual exige que al menos <strong>12</strong> valores de configuración difieran de la esfera base seleccionada; es un filtro de elegibilidad, no una promesa de aprobación.'),
      pair('Nesse momento explícito, o Firebase Authentication processa a credencial Google e as informações necessárias para autenticar você e emite um UID do Firebase Auth. O Svartifoss armazena esse UID — em vez do nome ou e-mail da sua conta Google — no documento de envio do Firestore como identificador de propriedade (<code>ownerUid</code>). Ele não mostra nem publica seu nome ou e-mail aos visitantes da galeria. Em vez disso, você escolhe o nome público do tema e um pseudônimo de autor ou o crédito público <strong>Anônimo</strong>.', 'En ese momento explícito, Firebase Authentication procesa la credencial de Google y la información necesaria para autenticarte y emite un UID de Firebase Auth. Svartifoss guarda ese UID — en lugar del nombre o correo de tu cuenta de Google — en el documento de envío de Firestore como identificador de propiedad (<code>ownerUid</code>). No muestra ni publica tu nombre o correo a los visitantes de la galería. En su lugar, eliges el nombre público del tema y un seudónimo de autor o el crédito público <strong>Anónimo</strong>.'),
      pair('O Firestore recebe um único registro imutável de envio <strong>pendente</strong>. Seu conteúdo inclui o ID público novo do tema; o JSON completo do perfil tipado e seu resumo de configurações; o nome público e o crédito público de autor escolhidos; a face base, revisão, versão do cliente e o registro de data e hora do servidor Firestore. Ele também inclui uma prévia de revisão WebP de 200&times;200 renderizada a partir da faixa de exemplo integrada ao Svartifoss, não da sua reprodução atual, capa ou metadados de mídia. Um moderador configurado pode depois adicionar apenas uma decisão de aprovação ou rejeição, seu UID de revisor e um registro de data e hora; nem o autor nem um moderador podem editar o conteúdo enviado pelo app.', 'Firestore recibe un único registro de envío <strong>pendiente</strong> e inmutable. Su contenido incluye el ID público nuevo del tema; el JSON completo del perfil tipado y su resumen de configuración; el nombre público y el crédito de autor elegidos; la esfera base, revisión, versión del cliente y marca de tiempo del servidor Firestore. También incluye una previsualización de revisión WebP de 200&times;200 renderizada a partir de la canción de muestra integrada de Svartifoss, no de tu reproducción actual, portada ni metadatos multimedia. Un moderador configurado solo puede añadir después una decisión de aprobación o rechazo, su UID de revisor y una marca de tiempo; ni el autor ni un moderador pueden editar desde la app el contenido enviado.'),
      pair('Anexar uma fotografia do seu relógio (opcional)', 'Adjuntar una fotografía de tu reloj (opcional)'),
      pair('A tela de envio permite anexar <strong>uma</strong> imagem da tela do Player pelo seletor de fotos do telefone. É totalmente opcional: não anexar nada é o caso normal e um tema enviado sem foto mostra apenas a prévia gerada. O Svartifoss não tira a foto — você escolhe uma imagem existente, e o app nunca lê sua galeria além do único arquivo entregue pelo seletor do sistema, que não exige permissão de armazenamento.', 'La pantalla de envío permite adjuntar <strong>una</strong> imagen de la pantalla Player desde el selector de fotos del teléfono. Es totalmente opcional: no adjuntar nada es lo normal y un tema enviado sin foto solo muestra la previsualización generada. Svartifoss no toma la foto — eliges una imagen existente y la app nunca lee tu galería más allá del único archivo que le entregas mediante el selector del sistema, que no requiere permiso de almacenamiento.'),
      pair('O que você anexa é publicado, e a tela de envio informa isso antes de abrir o seletor. A imagem é recortada em quadrado, redimensionada para no máximo 450&times;450 e recodificada como WebP no telefone; a recodificação remove metadados de câmera ou localização presentes no original. Depois, ela é armazenada no Firestore junto do envio, exibida a um moderador e — se aprovada — enviada ao repositório Git público deste projeto e servida pelo GitHub Pages. <strong>Tudo que estiver visível nela se torna público permanentemente</strong>, incluindo capa, nome da faixa, artista e horário que estiverem na tela do relógio, e permanece no histórico do repositório mesmo se o tema for removido depois. Um moderador pode aprovar o tema e recusar a foto; nesse caso, apenas o tema é publicado.', 'Lo que adjuntas se publica y la pantalla de envío lo indica antes de abrir el selector. La imagen se recorta a un cuadrado, se redimensiona como máximo a 450&times;450 y se vuelve a codificar como WebP en el teléfono; la recodificación elimina los metadatos de cámara o ubicación del original. Después se almacena en Firestore junto al envío, se muestra a un moderador y — si se aprueba — se incorpora al repositorio Git público de este proyecto y se sirve desde GitHub Pages. <strong>Todo lo visible en ella se vuelve público permanentemente</strong>, incluida la portada, nombre de la canción, artista y hora que aparezcan en la pantalla del reloj, y permanece en el historial del repositorio aunque el tema se retire. Un moderador puede aprobar el tema y rechazar su fotografía; en ese caso solo se publica el tema.'),
      pair('O Firestore também mantém um registro privado de cota ligado ao seu UID do Firebase Auth. Ele registra a contagem de envios, o ID do envio mais recente e o horário da janela necessário para limitar a no máximo <strong>dez</strong> envios de temas da comunidade em 24 horas. Ele não é público.', 'Firestore también mantiene un registro privado de cuota vinculado a tu UID de Firebase Auth. Registra el número de envíos, el ID del envío más reciente y la marca temporal de la ventana necesaria para limitar a un máximo de <strong>diez</strong> envíos de temas de la comunidad en 24 horas. No es público.'),
      pair('O Google processa dados de Authentication e Firestore sob a <a href="https://policies.google.com/privacy">Política de privacidade do Google</a> e os <a href="https://firebase.google.com/support/privacy">termos de processamento de dados do Firebase</a>.', 'Google procesa los datos de Authentication y Firestore según la <a href="https://policies.google.com/privacy">Política de privacidad de Google</a> y los <a href="https://firebase.google.com/support/privacy">términos de tratamiento de datos de Firebase</a>.'),
      pair('Moderação e publicação', 'Moderación y publicación'),
      pair('O registro pendente é privado para seu proprietário e para os moderadores configurados. A aprovação não torna um tema público imediatamente. Quando um envio aprovado é publicado, o publicador confiável o valida novamente e envia o JSON público do perfil, o nome público, o crédito de autor escolhido e qualquer fotografia aprovada ao repositório Git deste projeto; o GitHub Pages então serve esses arquivos públicos no catálogo. O UID do Firebase Auth e o nome/e-mail Google não são copiados para o repositório ou catálogo públicos.', 'El registro pendiente es privado para su propietario y los moderadores configurados. La aprobación no hace público un tema de inmediato. Cuando se publica un envío aprobado, el publicador confiable lo valida de nuevo y incorpora al repositorio Git de este proyecto el JSON público del perfil, el nombre público, el crédito de autor elegido y cualquier fotografía aprobada; GitHub Pages sirve después esos archivos públicos en el catálogo. El UID de Firebase Auth y el nombre/correo de Google no se copian al repositorio ni al catálogo públicos.'),
      pair('A versão 3.3 não implementa comentários nem envios de atualizações de temas.', 'La versión 3.3 no implementa comentarios ni envíos de actualizaciones de temas.'),
      pair('<strong>Meus envios</strong> (Conta da comunidade → Ver meus envios ou o botão de histórico na galeria da comunidade) lê os envios feitos por essa conta, com o status de cada um: aguardando análise, aprovado, publicado, rejeitado ou em remoção. Para um tema publicado, também mostra a contagem pública de curtidas já presente no catálogo baixado; nenhuma contagem por tema é solicitada ao Firebase.', '<strong>Mis envíos</strong> (Cuenta de la comunidad → Ver mis envíos o el botón de historial de la galería) lee los envíos realizados por esta cuenta, con el estado de cada uno: esperando revisión, aprobado, publicado, rechazado o en proceso de retirada. Para un tema publicado también muestra el recuento público de favoritos ya presente en el catálogo descargado; no se solicita a Firebase ninguna cifra por tema.'),
      pair('Nessa tela, você pode <strong>remover qualquer um dos seus temas</strong> sem excluir sua conta. É uma solicitação, não uma exclusão imediata, pelo mesmo motivo da exclusão de conta: o catálogo é um conjunto de arquivos no repositório Git deste projeto, então o publicador confiável remove o arquivo, a entrada do catálogo e as curtidas do tema na próxima execução, normalmente em até um dia, e depois exclui o registro de envio. Quem já instalou o tema mantém sua própria cópia local.', 'Desde esa pantalla puedes <strong>eliminar cualquiera de tus temas</strong> sin borrar tu cuenta. Es una solicitud y no una eliminación instantánea por el mismo motivo que la eliminación de cuenta: el catálogo es un conjunto de archivos en el repositorio Git de este proyecto, así que el publicador confiable elimina el archivo, la entrada del catálogo y los favoritos del tema en su siguiente ejecución, normalmente en un día, y después borra el registro de envío. Quien ya instaló el tema conserva su propia copia local.'),
      pair('Ele lê apenas registros cujo proprietário é o seu próprio UID do Firebase Auth; as regras do Firestore recusam os demais. Deliberadamente, ele não mostra quem analisou um envio — a identidade do revisor fica em um registro separado, acessível apenas aos moderadores, precisamente para que mostrar seus próprios resultados nunca revele essa identidade.', 'Solo lee registros cuyo propietario es tu propio UID de Firebase Auth; las reglas de Firestore rechazan los demás. Deliberadamente no muestra quién revisó un envío — la identidad del revisor se guarda en un registro separado solo para moderadores, precisamente para que mostrarte tus propios resultados nunca la revele.'),
      pair('Excluir sua conta da comunidade', 'Eliminar tu cuenta de la comunidad'),
      pair('<strong>Configurações → Geral → Temas da comunidade → Conta da comunidade → Excluir conta</strong> exclui a conta. Antes de enviar a solicitação, o app faz a pergunta que não pode responder por você — o que deve acontecer com os temas que você já publicou:', '<strong>Ajustes → General → Temas de la comunidad → Cuenta de la comunidad → Eliminar cuenta</strong> elimina la cuenta. Antes de enviarla, la app hace la pregunta que no puede responder por ti — qué debe ocurrir con los temas que ya publicaste:'),
      pair('<strong>Manter meus temas publicados.</strong> Eles permanecem no catálogo público sob o crédito de autor com que foram publicados, e o registro que os vincula à sua conta perde o seu UID do Firebase Auth.', '<strong>Conservar mis temas publicados.</strong> Permanecen en el catálogo público con el crédito de autor con el que se publicaron, y el registro que los vincula a tu cuenta pierde tu UID de Firebase Auth.'),
      pair('<strong>Excluir também meus temas publicados.</strong> Os arquivos de perfil público e as entradas do catálogo são removidos do repositório Git deste projeto na próxima publicação, junto com todas as curtidas registradas contra eles.', '<strong>Eliminar también mis temas publicados.</strong> Sus archivos de perfil público y entradas del catálogo se eliminan del repositorio Git de este proyecto en la siguiente publicación, junto con todos los favoritos registrados contra ellos.'),
      pair('Em qualquer escolha, a exclusão remove sua identidade do Firebase Authentication, seu registro privado de cota de envios, todos os documentos privados de curtidas criados por essa conta e qualquer envio seu que não seja público — um tema aguardando análise ou rejeitado é excluído nos dois casos, porque não há nada publicado a preservar.', 'En cualquiera de las dos opciones, la eliminación borra tu identidad de Firebase Authentication, tu registro privado de cuota de envíos, todos los documentos privados de favoritos creados por esa cuenta y cualquier envío tuyo que no sea público — un tema pendiente de revisión o rechazado se elimina en ambos casos, porque no hay nada publicado que conservar.'),
      pair('A solicitação é executada pelo mesmo publicador confiável que publica os temas, na próxima execução agendada, normalmente em até um dia. O app registra apenas sua decisão; ele nunca exclui sozinho o catálogo público ou a identidade, pois executar apenas a metade que o app alcança destruiria a conta deixando o conteúdo publicado para trás. Pelo mesmo motivo, a solicitação não pode ser editada ou retirada pelo app depois de confirmada, e a tela informa isso antes de pedir a confirmação.', 'La solicitud la ejecuta el mismo publicador confiable que publica los temas, en su siguiente ejecución programada, normalmente en un día. La app solo registra tu decisión; nunca elimina por sí sola el catálogo público ni la identidad, porque ejecutar solo la mitad a la que llega la app destruiría la cuenta y dejaría atrás el contenido publicado. Por el mismo motivo, la solicitud no se puede editar ni retirar desde la app una vez confirmada, y la pantalla lo indica antes de pedir confirmación.'),
      pair('Uma conta que existe apenas para curtidas, instalações ou denúncias — a conta anônima silenciosa descrita acima — pode ser excluída da mesma forma. Ela não possui temas, então não recebe essa pergunta; sua identidade e seus documentos privados de curtidas, instalações e denúncias são removidos.', 'Una cuenta que solo existe para favoritos, instalaciones o denuncias — la cuenta anónima silenciosa descrita arriba — se puede eliminar de la misma manera. No posee temas, por lo que no se le hace la pregunta; se eliminan su identidad y sus documentos privados de favoritos, instalaciones y denuncias.'),
      pair('É importante declarar dois limites. Remover um anúncio público não pode apagar informações já gravadas no histórico do Git ou copiadas para forks, clones, caches ou arquivos de terceiros, e quem já instalou um dos seus temas mantém sua própria cópia local. <strong>Remover deste dispositivo</strong>, exibido ao lado dele, é outra ação: apenas encerra a sessão localmente e não exclui nada. Desinstalar o app também remove os dados locais, mas não desfaz um envio nem uma reação privada já armazenada no Firestore.', 'Conviene dejar claros dos límites. Retirar un anuncio público no puede borrar información ya comprometida en el historial de Git o copiada en forks, clones, cachés o archivos de terceros, y quien ya instaló uno de tus temas conserva su propia copia local. <strong>Eliminar de este dispositivo</strong>, mostrado junto a él, es otra acción: solo cierra la sesión localmente y no borra nada. Desinstalar la app también elimina los datos locales, pero no retira un envío ni una reacción privada ya almacenada en Firestore.'),
      pair('Você pode remover uma única reação a qualquer momento tocando em <strong>Remover curtida</strong> na página de detalhes do tema, enquanto o app ainda mantiver o identificador que a criou. Registros de instalação e denúncia não podem ser removidos individualmente; excluir a conta da comunidade remove todos. Para solicitar a retirada do tema de outra pessoa ou ajuda para identificar um registro de tema da comunidade, envie um e-mail para o endereço em <a href="#contact">Contato</a>; essas solicitações são tratadas manualmente.', 'Puedes eliminar una reacción individual en cualquier momento tocando <strong>Quitar favorito</strong> en la página de detalles del tema, mientras la app conserve el identificador que la creó. Los registros de instalación y denuncia no se pueden eliminar individualmente; eliminar la cuenta de la comunidad los elimina todos. Para solicitar la retirada del tema de otra persona o ayuda para identificar un registro de tema de la comunidad, escribe a la dirección de <a href="#contact">Contacto</a>; esas solicitudes se gestionan manualmente.')
    ],
    'streaming-shortcut-artwork-optional': [
      pair('Capas de atalhos de streaming (opcional)', 'Portadas de accesos directos de streaming (opcional)'),
      pair('Se você salvar um atalho de playlist/faixa e ativar <strong>Buscar capas de atalhos online</strong> (Configurações → Apps → Música e serviços — <strong>desativado por padrão</strong>), o Svartifoss envia o link público compartilhado desse atalho ao endpoint público <strong>oEmbed</strong> do serviço de streaming correspondente (Spotify, YouTube, SoundCloud ou Deezer) para baixar uma miniatura, exibida no telefone, no menu do relógio e em qualquer botão ao qual você a atribua. Cada miniatura é buscada uma vez e armazenada em cache no dispositivo.', 'Si guardas un acceso directo de lista/canción y activas <strong>Obtener portadas de accesos directos en línea</strong> (Ajustes → Apps → Música y servicios — <strong>desactivado por defecto</strong>), Svartifoss envía el enlace público compartido de ese acceso directo al endpoint público <strong>oEmbed</strong> del servicio correspondiente (Spotify, YouTube, SoundCloud o Deezer) para descargar una miniatura, mostrada en el teléfono, el menú del reloj y cualquier botón al que la asignes. Cada miniatura se obtiene una vez y se guarda en caché en el dispositivo.'),
      pair('Somente o próprio link — uma URL pública que você escolheu salvar — é enviado; nenhuma conta, chave de API ou outro dado pessoal é anexado. A solicitação vai diretamente ao serviço de streaming, não passa por nenhum servidor nosso e é regida pela política de privacidade desse serviço, não por esta. Apple Music, Amazon Music e Tidal não têm um endpoint oEmbed público, então os atalhos desses serviços sempre usam um ícone genérico do app.', 'Solo se envía el enlace — una URL pública que elegiste guardar —; no se adjunta ninguna cuenta, clave de API ni otro dato personal. La solicitud va directamente al servicio de streaming, no pasa por ningún servidor nuestro y se rige por la política de privacidad de ese servicio, no por esta. Apple Music, Amazon Music y Tidal no tienen un endpoint oEmbed público, por lo que sus accesos directos siempre usan un icono genérico de la app.')
    ],
    'queue-covers': [
      pair('Capas da fila de reprodução (opcional)', 'Portadas de la cola de reproducción (opcional)'),
      pair('Os apps de música publicam a capa de cada item da fila de uma de duas formas, e nenhuma é lida sem sua autorização.', 'Las apps de música publican la portada de cada elemento de la cola de una de dos formas, y ninguna se lee si no lo autorizas.'),
      pair('<strong>Da sua biblioteca.</strong> Players locais (Retro Music e similares) referenciam uma capa já armazenada no dispositivo. Lê-las exige a permissão de música e áudio do Android, solicitada na linha "Capas da fila da sua biblioteca" em Configurações → Apps. É uma leitura puramente local — não há acesso à rede e nada sobre sua biblioteca é enviado, transmitido ao relógio além das capas dos até 20 itens exibidos ou compartilhado com alguém. As mesmas capas são usadas pela própria folha de fila do telefone; ela permanece no telefone e nunca é transmitida. Recusar deixa as duas filas funcionando com miniaturas vazias.', '<strong>De tu biblioteca.</strong> Los reproductores locales (Retro Music y similares) hacen referencia a una portada ya guardada en el dispositivo. Leerlas requiere el permiso de música y audio de Android, solicitado en la opción «Portadas de la cola de tu biblioteca» de Ajustes → Apps. Es una lectura puramente local — no hay acceso a la red y nada de tu biblioteca se sube, se transmite al reloj más allá de las portadas de los hasta 20 elementos mostrados ni se comparte. Las mismas portadas son las que dibuja la hoja de cola del teléfono; esa hoja permanece en el teléfono y nunca se transmite. Rechazar el permiso deja ambas colas funcionando con miniaturas vacías.'),
      pair('<strong>Da internet.</strong> Clientes de streaming publicam uma URL de capa em vez de uma imagem. <strong>Buscar capas da fila online</strong> (Configurações → Apps e a seção Painéis da aba Face do relógio) baixa cada capa uma vez e a armazena no telefone, tanto para a fila do relógio quanto para a própria fila do telefone. Somente a URL publicada pelo app de música é solicitada; nenhuma conta, chave de API ou dado pessoal é anexado, e a solicitação vai diretamente ao host indicado pelo app, não a um servidor nosso.', '<strong>De internet.</strong> Los clientes de streaming publican una URL de portada en lugar de una imagen. <strong>Obtener portadas de la cola en línea</strong> (Ajustes → Apps y la sección Paneles de la pestaña Esfera del reloj) descarga cada portada una vez y la guarda en el teléfono, para la cola del reloj y la hoja de cola del propio teléfono. Solo se solicita la URL publicada por la app de música; no se adjunta ninguna cuenta, clave de API ni dato personal, y la solicitud va directamente al host indicado por esa app, no a un servidor nuestro.'),
      pair('Essa opção vem <strong>ativada por padrão</strong>, ao contrário das capas de atalhos opcionais. O motivo é que a fila de um app de streaming não tem outra fonte de capas; deixá-la desativada produzia linhas permanentemente vazias, em vez de uma versão degradada. Desativá-la é uma única chave e, com ela desligada, capas remotas são totalmente ignoradas e os itens mostram miniaturas vazias — a fila e todo o restante do app continuam funcionando offline.', 'Esta opción está <strong>activada por defecto</strong>, a diferencia de las portadas opcionales de accesos directos. La razón es que la cola de una app de streaming no tiene otra fuente de portadas; dejarla desactivada producía filas permanentemente vacías en vez de una versión degradada. Desactivarla es un solo interruptor y, al hacerlo, se omiten por completo las portadas remotas y esos elementos muestran miniaturas vacías — la cola y todo lo demás en la app siguen funcionando sin conexión.'),
      pair('A mesma chave também controla uma solicitação fora da fila. Alguns apps de streaming fornecem uma miniatura pequena da faixa que está <em>tocando</em> — dimensionada para a própria notificação do telefone, às vezes com apenas 100 pixels — enquanto as mesmas informações carregam o endereço da capa em tamanho completo. Como o relógio amplia essa imagem para preencher a tela, a pequena fica visivelmente borrada. Quando essa opção está ligada e somente quando a imagem fornecida é menor do que o relógio precisa, a cópia maior é buscada no mesmo endereço e armazenada junto das capas da fila. É o mesmo tipo de solicitação, para o endereço publicado pelo app, sem dados anexados e sem servidor nosso. Com a opção desligada, a imagem pequena é usada como está.', 'El mismo interruptor también controla una solicitud fuera de la cola. Algunas apps de streaming entregan una miniatura pequeña de la canción que se está <em>reproduciendo</em> — dimensionada para su propia notificación del teléfono, a veces de solo 100 píxeles — mientras la misma información contiene la dirección de la portada completa. Como el reloj amplía esa imagen para llenar la pantalla, la pequeña se ve borrosa. Cuando la opción está activa, y solo cuando la imagen proporcionada es menor de lo que necesita el reloj, se obtiene la copia grande de esa misma dirección y se guarda junto a las portadas de la cola. Es el mismo tipo de solicitud, a la dirección publicada por la app, sin datos adjuntos ni servidor nuestro. Con la opción desactivada se usa la imagen pequeña tal cual.')
    ],
    'track-details': [
      pair('Detalhes da faixa', 'Detalles de la canción'),
      pair('A face <strong>Metadata</strong> do relógio mostra o que a faixa realmente é: álbum, posição no disco, créditos, ano e, para uma faixa armazenada no telefone, formato, bitrate, taxa de amostragem, canais e tamanho do arquivo.', 'La esfera <strong>Metadata</strong> del reloj muestra qué es realmente la canción: álbum, posición en el disco, créditos, año y, si está almacenada en el teléfono, formato, bitrate, frecuencia de muestreo, canales y tamaño del archivo.'),
      pair('Quase tudo isso não exige rede. Álbum, artista, créditos, gênero, ano e posição vêm das tags que o app de reprodução já publica sobre a música atual, e os detalhes do arquivo são lidos do arquivo no telefone — por isso aparecem apenas para faixas locais e somente quando o acesso à mídia descrito acima foi concedido. Nada disso sai dos seus dispositivos.', 'Casi todo esto no necesita red. El álbum, artista, créditos, género, año y posición proceden de las etiquetas que la app de reproducción ya publica sobre la canción actual, y los detalles del archivo se leen del archivo del teléfono — por eso solo aparecen para canciones locales y cuando se ha concedido el acceso multimedia descrito arriba. Nada de esto sale de tus dispositivos.'),
      pair('Uma parte opcional usa a internet. <strong>Buscar detalhes da faixa online</strong> (Configurações → Apps → Música e serviços) envia o <strong>nome da faixa e o nome do artista</strong> ao <a href="https://musicbrainz.org">MusicBrainz</a>, um banco público gratuito de música, para preencher detalhes que o app não publicou — ISRC, gravadora, data de lançamento e os IDs do próprio catálogo do MusicBrainz. Nada mais é anexado: nenhum identificador, conta, histórico de reprodução ou registro de qual app estava tocando. A solicitação vai diretamente ao MusicBrainz, não a um servidor nosso, e é regida pelos termos desse serviço, não por esta política.', 'Una parte opcional usa internet. <strong>Buscar detalles de la canción en línea</strong> (Ajustes → Apps → Música y servicios) envía el <strong>nombre de la canción y del artista</strong> a <a href="https://musicbrainz.org">MusicBrainz</a>, una base pública y gratuita de música, para completar detalles que la app no publicó — el ISRC, el sello, la fecha de lanzamiento y los identificadores de su catálogo. No se adjunta nada más: ningún identificador, cuenta, historial de escucha ni registro de qué app estaba reproduciendo. La solicitud va directamente a MusicBrainz, no a un servidor nuestro, y se rige por los términos de ese servicio, no por esta política.'),
      pair('Isso vem <strong>desativado por padrão</strong>, ao contrário da busca de letras, e a diferença é intencional: uma letra não tem uma segunda fonte, enquanto este recurso apenas <em>adiciona</em> linhas a uma tabela que já se baseia nas tags do player. Deixá-lo desligado custa algumas linhas, não o recurso. Nada é enviado a menos que você o ative <strong>e</strong> selecione a face Metadata — nenhuma outra face faz essa solicitação. Os resultados ficam apenas na memória enquanto o app do telefone está em execução e nunca são gravados no disco.', 'Está <strong>desactivado por defecto</strong>, a diferencia de la búsqueda de letras, y la diferencia es intencionada: una letra no tiene una segunda fuente, mientras que esta opción solo <em>añade</em> filas a una tabla que ya depende de las etiquetas del reproductor. Dejarla desactivada solo cuesta unas líneas, no la función. No se envía nada a menos que la actives <strong>y</strong> selecciones la esfera Metadata — ninguna otra esfera la solicita. Los resultados se mantienen en memoria mientras la app del teléfono está en ejecución y nunca se escriben en disco.')
    ],
    lyrics: [
      pair('Letras de músicas', 'Letras de canciones'),
      pair('O relógio tem duas superfícies de letras: uma tela que você pode colocar em qualquer botão, gesto ou espaço do menu e a face <strong>Verse</strong>, que mostra a linha cantada na tela principal do player. Qualquer uma delas pede ao <strong>telefone</strong> que busque as palavras — o relógio nunca faz essa solicitação, pois um relógio pareado por Bluetooth não possui conexão própria com a internet.', 'El reloj tiene dos superficies de letras: una pantalla que puedes asignar a cualquier botón, gesto o espacio del menú y la esfera <strong>Verse</strong>, que muestra la línea cantada en la pantalla principal del reproductor. Cualquiera de las dos pide al <strong>teléfono</strong> que busque las palabras — el reloj nunca hace la solicitud, ya que un reloj emparejado por Bluetooth no tiene conexión propia a internet.'),
      pair('O telefone envia o <strong>nome da faixa, o nome do artista e a duração da faixa</strong> ao <a href="https://lrclib.net">LRCLIB</a>, um banco público gratuito de letras, que faz a correspondência exatamente com esses três dados e não exige conta ou chave de API. Nada mais é anexado: nenhum identificador, conta, histórico de reprodução ou registro de qual app estava tocando. A solicitação vai diretamente ao LRCLIB, não a um servidor nosso, e é regida pelos termos desse serviço, não por esta política.', 'El teléfono envía el <strong>nombre de la canción, el nombre del artista y la duración</strong> a <a href="https://lrclib.net">LRCLIB</a>, una base pública y gratuita de letras, que busca exactamente con esos tres datos y no requiere cuenta ni clave de API. No se adjunta nada más: ningún identificador, cuenta, historial de escucha ni registro de qué app estaba reproduciendo. La solicitud va directamente a LRCLIB, no a un servidor nuestro, y se rige por los términos de ese servicio, no por esta política.'),
      pair('Nada é solicitado a menos que uma dessas duas superfícies esteja em uso. Abrir a tela de letras busca a faixa atual; selecionar a face Verse busca cada faixa enquanto ela permanece selecionada, pois seu objetivo é acompanhar as palavras. Escolha qualquer outra face e nunca abra a tela de letras, e nenhuma consulta acontecerá. As letras retornadas ficam <strong>apenas na memória</strong> enquanto o app do telefone está em execução e nunca são gravadas no disco; fechar o app as esquece.', 'No se solicita nada a menos que una de esas dos superficies esté en uso. Abrir la pantalla de letras busca la canción actual; seleccionar la esfera Verse busca cada canción mientras permanece seleccionada, ya que su propósito es seguir las palabras. Elige cualquier otra esfera y no abras la pantalla de letras, y no se realizará ninguna consulta. Las letras recibidas se mantienen <strong>solo en memoria</strong> mientras la app del teléfono está en ejecución y nunca se escriben en disco; al cerrar la app se olvidan.'),
      pair('Isso vem <strong>ativado por padrão</strong>, pelo mesmo motivo das capas da fila: uma letra não tem uma segunda fonte, então desativá-la não degrada a tela, apenas a deixa vazia. <strong>Buscar letras online</strong> (Configurações → Apps → Música e serviços) desativa o recurso, e as duas superfícies passam a informar que as consultas estão desativadas. Todo o restante do app continua funcionando offline.', 'Está <strong>activado por defecto</strong>, por la misma razón que las portadas de la cola: una letra no tiene una segunda fuente, por lo que desactivarla no degrada la pantalla, simplemente la deja vacía. <strong>Buscar letras en línea</strong> (Ajustes → Apps → Música y servicios) lo desactiva, y ambas superficies informan que las consultas están desactivadas. Todo lo demás de la app sigue funcionando sin conexión.')
    ],
    'usage-diagnostics': [
      pair('Diagnósticos de uso', 'Diagnósticos de uso'),
      pair('O app do telefone também inclui o <strong>Google Analytics para Firebase</strong>. Ele coleta eventos automáticos padrão de app/sessão do Firebase e contexto técnico, como versão do app, classe do dispositivo/sistema e um identificador ligado à instalação. O Svartifoss não associa conta, nome, e-mail, metadados de mídia ou conteúdo de mensagens a esses eventos e não registra eventos personalizados do Analytics. O serviço é regido pela <a href="https://policies.google.com/privacy">Política de privacidade do Google</a> e pelas <a href="https://firebase.google.com/support/privacy">informações de privacidade do Firebase</a>. A opção de relatórios de falha descrita acima controla os relatórios do Crashlytics; ela não controla esses eventos automáticos separados do Analytics.', 'La app del teléfono también incluye <strong>Google Analytics para Firebase</strong>. Recopila eventos automáticos estándar de app/sesión de Firebase y contexto técnico, como la versión de la app, la clase de dispositivo/sistema operativo y un identificador asociado a la instalación. Svartifoss no asocia una cuenta, nombre, correo, metadatos multimedia ni contenido de mensajes a estos eventos y no registra eventos personalizados de Analytics. El servicio se rige por la <a href="https://policies.google.com/privacy">Política de privacidad de Google</a> y la <a href="https://firebase.google.com/support/privacy">información de privacidad de Firebase</a>. La opción de informes de fallos descrita arriba controla los informes de Crashlytics; no controla estos eventos automáticos independientes de Analytics.')
    ],
    'what-we-dont-do': [
      pair('O que não fazemos', 'Lo que no hacemos'),
      pair('Não exigimos uma conta para usar os controles de reprodução, navegar pelos temas da comunidade ou curtir, instalar ou denunciar um tema. Um login opcional do Google é oferecido apenas quando você envia explicitamente um tema da comunidade.', 'No exigimos una cuenta para usar los controles de reproducción, explorar temas de la comunidad ni marcar, instalar o denunciar uno. Solo se ofrece un inicio de sesión opcional de Google cuando envías explícitamente un tema de la comunidad.'),
      pair('Não operamos um servidor próprio pelo qual seus dados passem.', 'No operamos un servidor propio por el que pasen tus datos.'),
      pair('Não vendemos, alugamos nem compartilhamos seus dados com anunciantes ou corretores de dados.', 'No vendemos, alquilamos ni compartimos tus datos con anunciantes o intermediarios de datos.'),
      pair('Não exibimos anúncios.', 'No mostramos anuncios.'),
      pair('Não lemos o conteúdo de notificações não relacionadas. Para o app de mídia atual, usamos apenas metadados de reprodução e — quando selecionados explicitamente — os rótulos e ícones das ações de mídia.', 'No leemos el contenido de notificaciones no relacionadas. Para la app multimedia actual, solo usamos metadatos de reproducción y — cuando se seleccionan explícitamente — sus etiquetas e iconos de acciones multimedia.'),
      pair('Não capturamos a tela do seu relógio. As únicas imagens que o Svartifoss publica são as que você escolhe e anexa a um envio de tema da comunidade.', 'No capturamos la pantalla de tu reloj. Las únicas imágenes que Svartifoss publica son las que tú eliges y adjuntas a un envío de tema de la comunidad.')
    ],
    children: [
      pair('Privacidade infantil', 'Privacidad infantil'),
      pair('O Svartifoss não é direcionado a crianças e não coleta conscientemente informações de crianças.', 'Svartifoss no está dirigido a niños y no recopila conscientemente información de niños.')
    ],
    'open-source': [
      pair('Código aberto', 'Código abierto'),
      pair('O Svartifoss é um software gratuito e de código aberto (GPLv3). Qualquer pessoa pode inspecionar o código-fonte completo — incluindo tudo que é descrito nesta política — em: <a href="https://github.com/gabrielluizone/Svartifoss">github.com/gabrielluizone/Svartifoss</a>', 'Svartifoss es software gratuito y de código abierto (GPLv3). Cualquiera puede inspeccionar el código fuente completo — incluido todo lo descrito en esta política — en: <a href="https://github.com/gabrielluizone/Svartifoss">github.com/gabrielluizone/Svartifoss</a>')
    ],
    changes: [
      pair('Alterações nesta política', 'Cambios en esta política'),
      pair('Se esta política mudar, a versão atualizada será publicada neste mesmo local com uma nova data de "Última atualização".', 'Si esta política cambia, la versión actualizada se publicará en esta misma ubicación con una nueva fecha de «Última actualización».')
    ],
    contact: [
      pair('Contato', 'Contacto'),
      pair('Perguntas sobre esta política ou seus dados, incluindo uma solicitação de retirada ou remoção de um tema da comunidade, podem ser enviadas para: <strong>gabrielsvafoss@gmail.com</strong>', 'Las preguntas sobre esta política o tus datos, incluidas las solicitudes de retirada o eliminación de un tema de la comunidad, se pueden enviar a: <strong>gabrielsvafoss@gmail.com</strong>')
    ]
  };

  var selector = document.getElementById('language-select');
  var supported = { en: true, 'pt-BR': true, es: true };
  var language = 'en';

  try {
    var stored = window.localStorage.getItem('svartifoss-language');
    if (stored && supported[stored]) language = stored;
  } catch (ignore) {}

  function rememberSource(element) {
    var source = element.getAttribute('data-i18n-source');
    if (source === null) {
      source = element.innerHTML;
      element.setAttribute('data-i18n-source', source);
    }
    return source;
  }

  function normalizeMarkup(markup) {
    return markup.replace(/\r?\n|\r/g, ' ').replace(/[\t ]{2,}/g, ' ');
  }

  function applyNodes(nodes, entries) {
    if (nodes.length !== entries.length) console.warn('Svartifoss privacy translation count mismatch', nodes.length, entries.length);
    nodes.forEach(function (node, index) {
      var source = rememberSource(node);
      var translation = entries[index] && entries[index][language];
      node.innerHTML = normalizeMarkup(language === 'en' ? source : (translation || source));
    });
  }

  function translatePage(nextLanguage) {
    language = supported[nextLanguage] ? nextLanguage : 'en';
    document.documentElement.lang = language;
    if (selector) {
      selector.value = language;
      selector.setAttribute('aria-label', language === 'en' ? 'Language' : 'Idioma');
    }

    applyNodes(document.querySelectorAll('.doc-hero .eyebrow, .doc-hero h1, .doc-updated, .doc-lede, .callout p'), header);
    applyNodes(document.querySelectorAll('.toc-label, .toc a'), toc);
    Object.keys(sections).forEach(function (id) {
      var section = document.getElementById(id);
      if (!section) return;
      applyNodes(section.querySelectorAll('h2, h3, h4, p, th, td, li'), sections[id]);
    });

    var navHome = document.querySelector('.nav-links a[href="index.html"]');
    if (navHome) navHome.textContent = language === 'en' ? 'Home' : (language === 'pt-BR' ? 'Início' : 'Inicio');
    var footerNodes = document.querySelectorAll('.footer-links a, .footer-meta span');
    var footer = [
      language === 'en' ? 'GitHub <svg class="icon"><use href="#i-open-new"></use></svg>' : 'GitHub <svg class="icon"><use href="#i-open-new"></use></svg>',
      language === 'en' ? 'Releases <svg class="icon"><use href="#i-open-new"></use></svg>' : (language === 'pt-BR' ? 'Lançamentos <svg class="icon"><use href="#i-open-new"></use></svg>' : 'Versiones <svg class="icon"><use href="#i-open-new"></use></svg>'),
      'Buy Me a Coffee <svg class="icon"><use href="#i-open-new"></use></svg>',
      'Ko-fi <svg class="icon"><use href="#i-open-new"></use></svg>',
      language === 'en' ? 'License' : (language === 'pt-BR' ? 'Licença' : 'Licencia'),
      'com.svartifoss.snfell · GPL-3.0',
      language === 'en' ? 'A continuation of <a href="https://github.com/matejdro/WearMusicCenter">Music Center for Wear</a> by matejdro' : (language === 'pt-BR' ? 'Uma continuação do <a href="https://github.com/matejdro/WearMusicCenter">Music Center for Wear</a> de matejdro' : 'Una continuación de <a href="https://github.com/matejdro/WearMusicCenter">Music Center for Wear</a> de matejdro')
    ];
    footerNodes.forEach(function (node, index) {
      var source = rememberSource(node);
      node.innerHTML = language === 'en' ? source : footer[index];
    });

    document.title = language === 'en' ? 'Privacy Policy — Svartifoss' : (language === 'pt-BR' ? 'Política de privacidade — Svartifoss' : 'Política de privacidad — Svartifoss');
    var description = document.querySelector('meta[name="description"]');
    if (description) description.setAttribute('content', language === 'en' ? 'How Svartifoss handles your data: no accounts, no ads, no servers of ours. What the app accesses, what stays on-device, and which optional features talk to the internet.' : (language === 'pt-BR' ? 'Como o Svartifoss trata seus dados: sem contas, anúncios ou servidores próprios. O que o app acessa, o que permanece no dispositivo e quais recursos opcionais acessam a internet.' : 'Cómo gestiona Svartifoss tus datos: sin cuentas, anuncios ni servidores propios. Qué accede la app, qué permanece en el dispositivo y qué funciones opcionales usan internet.'));

    try { window.localStorage.setItem('svartifoss-language', language); } catch (ignore) {}
  }

  if (selector) selector.addEventListener('change', function () { translatePage(selector.value); });
  translatePage(language);
})();
